Cj.Eq(s, "xxxxx", "5 chars");
Cj.Eq(Solution.RepeatChar('a', 0), "", "empty for 0");

// Probe first (calibrated on this runtime: a tier-0 string.Create call
// allocates ~312 B even when the payload is 200 B — the lambda + engine
// overhead). The bound must allow that overhead but explode on ANY
// intermediate string: one O(n) concat chain allocates >= 400*152.
var probe = GC.GetAllocatedBytesForCurrentThread();
for (int i = 0; i < 100; i++) Solution.RepeatChar('y', 100);
var fast = GC.GetAllocatedBytesForCurrentThread() - probe;
Cj.True(fast <= 100 * 400, $"string.Create path within budget (got {fast}; an intermediate-building path exceeds 6,080,000)");

int f() => 42;
var d = Solution.Measure(f, 10);
Cj.True(d >= 0, "delegates measured after warmup; no negative/first-call noise");
